from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # constants
    a = [7, 10, 5, 3, 9]
    sum_qubits = ancilla_qubits          # all ancillas used as sum register (LSB first)
    n_sum = len(sum_qubits)

    def controlled_increment(ctrl, forward=True):
        """Apply a controlled +1 (increment) or -1 (decrement) to the sum register."""
        if forward:
            qc.cx(ctrl, sum_qubits[0])
            for k in range(1, n_sum):
                controls = [ctrl] + sum_qubits[:k]
                qc.mcx(controls, sum_qubits[k], mode='noancilla')
        else:
            for k in range(n_sum - 1, 0, -1):
                controls = [ctrl] + sum_qubits[:k]
                qc.mcx(controls, sum_qubits[k], mode='noancilla')
            qc.cx(ctrl, sum_qubits[0])

    # Compute sum of selected elements
    for i, val in enumerate(a):
        for _ in range(val):
            controlled_increment(problem_qubits[i], forward=True)

    # Phase flip: -1 iff sum == 16 (binary 010000)
    # Flip bits that should be 0 to 1 (bits 0,1,2,3,5)
    flip_bits = [0, 1, 2, 3, 5]
    for idx in flip_bits:
        qc.x(sum_qubits[idx])
    qc.h(sum_qubits[4])
    controls = [sum_qubits[idx] for idx in flip_bits]
    qc.mcx(controls, sum_qubits[4], mode='noancilla')
    qc.h(sum_qubits[4])
    for idx in flip_bits:
        qc.x(sum_qubits[idx])

    # Uncompute sum (reverse order)
    for i in range(len(a) - 1, -1, -1):
        for _ in range(a[i]):
            controlled_increment(problem_qubits[i], forward=False)

