    s = ancilla_qubits  # alias

    # helper to add a constant 2^j to the sum register, controlled by p
    def add_power_of_two(p, j, forward=True):
        if forward:
            # add 2^j: process k from high to low
            for k in range(n_sum - 1, j - 1, -1):
                if k == j:
                    qc.cx(p, s[j])
                else:
                    controls = [p] + [s[b] for b in range(j, k)]
                    qc.mcx(controls, s[k], mode='noancilla')
        else:
            # inverse: process k from low to high
            for k in range(j, n_sum):
